function msg(text, cls) {
  G.log.push({ text: text, cls: cls || '' });
  if (G.log.length > 3) G.log.shift();
  if (pickupFeedback) { pickupFeedback.logChanged = true; return; }
  logEl.innerHTML = G.log.map(function (m) { return '<div class="line ' + m.cls + '">' + m.text + '</div>'; }).join('');
}
function toast(text, cls) {
  if (pickupFeedback) {
    var pending = pickupFeedback.toasts;
    var last = pending.length ? pending[pending.length - 1].text : toastsEl.lastElementChild && toastsEl.lastElementChild.textContent;
    if (last === text) return;
    if (pending.length >= 2) pending.shift();
    pending.push({ text: text, cls: cls });
    return;
  }
  if (toastsEl.lastElementChild && toastsEl.lastElementChild.textContent === text) return;
  while (toastsEl.children.length >= 2) toastsEl.removeChild(toastsEl.firstElementChild);
  var d = document.createElement('div');
  d.className = 'toast ' + (cls || '');
  d.textContent = text;
  toastsEl.appendChild(d);
  setTimeout(function () { d.style.transition = 'opacity .3s'; d.style.opacity = '0'; setTimeout(function () { d.remove(); }, 320); }, 1700);
}
function flushPickupFeedback(feedback) {
  if (feedback.logChanged) logEl.innerHTML = G.log.map(function (entry) { return '<div class="line ' + entry.cls + '">' + entry.text + '</div>'; }).join('');
  feedback.toasts.forEach(function (entry) { toast(entry.text, entry.cls); });
  Object.keys(feedback.sounds).forEach(function (name) { window.NeonAudio.sfx[name](); });
}
