        var land = null;
        for (var ps = 1; ps <= 3; ps++) {
          var lx = p.x + dx * ps, ly = p.y + dy * ps;
          if (lx < 0 || ly < 0 || lx >= MAP_W || ly >= MAP_H) break;
          if (G.map[ly][lx] === WALL || enemyAt(lx, ly)) continue;
          land = { x: lx, y: ly };
          break;
        }
        if (land) {
          p.x = land.x; p.y = land.y;
          p.face = Math.atan2(dy, dx);
          burst(p.x, p.y, C.violet, 8);
          sfx.step();
          pickup(p.x, p.y);
          checkSpecial();
          if (G.paused) return;
          endTurn();
          return;
        }
        msg('墙后没有落点', 'dim');
