  var format = function (number) { return String(Math.round(number * 10000) / 100); };
  var text = Object.keys(upgrade.stat).map(function (key) {
    var value = upgrade.stat[key] * count;
    if (key === 'hp') return '起始生命 +' + value;
    if (key === 'def') return '起始防御 +' + value;
    if (key === 'atk') return '起始攻击 +' + value;
    if (key === 'dodge') return '闪避 +' + format(value) + '%';
    if (key === 'crit') return '暴击 +' + format(value) + '%';
    if (key === 'items') return '开局额外携带 ' + value + ' 件消耗品（上限 2 件）';
    if (key === 'prepCyber') return '出发前可多选 ' + value + ' 件初始义体';
    if (key === 'prepReroll') return '初始义体可重掷 ' + value + ' 次';
    if (key === 'dropNormal') return '普通敌人义体掉率 +' + format(value) + '%';
    if (key === 'dropElite') return '精英义体掉率 +' + format(value) + '%';
    if (key === 'dropBoss') return '守卫义体掉率 +' + format(value) + '%';
    if (key === 'dropQuality') return '掉落品质相当于深 ' + Math.round(value * 300) / 10 + ' 层';
    if (key === 'adapt') return '义体适应度 +' + value;
    if (key === 'psyRes') return '赛博精神病发作率 -' + format(value) + '%';
    if (key === 'chipLoad') return '芯片负载 -' + format(value) + '%';
    if (key === 'psyShort') return '失控持续时间 -' + value + ' 回合（至少 1 回合）';
    if (key === 'ovTune') return '过载造成的效能衰减 -' + format(value) + '%';
    if (key === 'syncPow') return '未过载时，义体主动技能功率 +' + format(value) + '%';
    return upgrade.desc;
  }).join(' · ');
  return (complete ? '累计 · ' : '下一级 · ') + text;
