/* =========================================================
   流程
   ========================================================= */


function prepScreen(opts) {
  if (META.pendingPrepTransfer && !reconcilePreparedTransfer()) { sfx.hurt(); return; }
  var flow = opts && opts.flow;
  var picks = 1 + metaStatSum('prepCyber');
  var rerolls = metaStatSum('prepReroll');
  var cps = [], sps = [], sel = [], consSel = null, stashSel = [];
  function roll() {
    var empty = shuffle(CYBER_SLOTS.map(function (s) { return s.id; }));
    cps = [];
    empty.forEach(function (slot) {
      if (cps.length >= 3) return;
      var cand = normalMods().filter(function (m) { return slotAccepts(m, slot); });
      var one = pickCyber(cand);
      if (one && !cps.some(function (x) { return x.id === one.id; })) cps.push(one);
    });
    sps = [pickConsumable(1)]; for (var sg = 0; sg < 8 && sps.length < 2; sg++) { var sc = pickConsumable(1); if (sc.id !== sps[0].id) sps.push(sc); } if (sps.length < 2) sps.push(pickConsumable(1));
    sel = [];
    consSel = sps[0].id;
  }
  roll();
  function render() {
    var nxCh = (STORY.chapters || []).filter(function (c) { return c.lock && !ST.chapters[c.id]; }).sort(function (a, b) { return a.lock.chal - b.lock.chal; })[0];
    var flowbar = flow ? menuStepper(3, '战备', '<span style="width:32px"></span>') : '';
    var lockTxt = nxCh ? '<div class="m3-lockline">下一段主线要求挑战树 ≥ ' + nxCh.lock.chal + ' 项通关 · 当前选了 ' + (G.chalSel.length || 0) + ' 项</div>' : '';
    var html = '<div class="card' + (flow ? ' m3-prep' : '') + '" style="--mc:' + classDef().color + '">' + flowbar + (flow ? '<div class="m3-prepsub"><b>' + econEsc(mnStoryTitle(classDef().id) || classDef().name) + '</b><span>可选 ' + picks + ' 件初始义体 · 已选 ' + sel.length + '/' + picks + '</span></div>' : '<div class="kicker">战备采购 · 初始义体</div><h1 class="title small">出发前</h1><div class="sub">可选 ' + picks + ' 件义体 · 已选 ' + sel.length + '/' + picks + '</div>') + '%%PGAUGE%%' + lockTxt +
      '<div class="cx-h" style="margin-top:10px">初始义体 · 选 ' + picks + ' 件</div>';
    cps.forEach(function (m) {
      var q = QUALITY[m.quality] || QUALITY.gray;
      var on = sel.indexOf(m.id) >= 0;
      html += '<button class="boon" data-pcyber="' + m.id + '" style="width:100%;margin-bottom:6px;border-color:' + (on ? q.color : 'rgba(120,140,160,.3)') + ';background:' + (on ? 'rgba(34,230,255,.08)' : 'transparent') + '">' +
        '<span class="rarity" style="color:' + q.color + '">' + q.name + ' · ' + q.slots + ' 芯片槽</span><b>' + m.name + '</b>' +
        '<em style="display:block;font-style:normal;font-size:10px;color:#7fa;margin-top:3px">' + m.desc + '</em></button>';
    });
    if (rerolls > 0) {
      html += '<button class="ghost" id="prepReroll" style="margin-top:2px;border-color:rgba(252,238,10,.45);color:#fcee0a">重掷选项 · 剩余 ' + rerolls + '</button>';
    }
    html += '<div class="cx-h" style="margin-top:10px">战备</div>';
    sps.forEach(function (c) {
      var on = consSel === c.id;
      html += '<button class="boon" data-pcons="' + c.id + '" style="width:100%;margin-bottom:6px;border-color:' + (on ? c.color : 'rgba(120,140,160,.3)') + '"><b style="color:' + ((TIER_INFO[c.tier] || TIER_INFO.common).color) + '">' + c.name + '</b><span class="rarity">' + (TIER_INFO[c.tier] || TIER_INFO.common).name + '</span><em style="display:block;font-style:normal;font-size:10px;color:#7fa;margin-top:3px">' + consEffectText(c).join('；') + '</em></button>';
    });
    if (META.stash.cyber.length) {
      html += '<div class="cx-h" style="margin-top:10px">仓库义体 · 带入（已选 ' + stashSel.length + '）</div><div class="stash-grid">';
      var order = META.stash.cyber.map(function (x, i) { return i; }).sort(function (a, b) { var A = stashSel.indexOf(a) >= 0, B = stashSel.indexOf(b) >= 0; if (A !== B) return A ? -1 : 1; var ma = MOD_BY[stashId(META.stash.cyber[a])], mb = MOD_BY[stashId(META.stash.cyber[b])]; return Q_ORDER.indexOf(mb ? mb.quality : 'gray') - Q_ORDER.indexOf(ma ? ma.quality : 'gray'); });
      var limit = G._prepAll ? order.length : 8;
      order.slice(0, limit).forEach(function (itemIndex) { var item = META.stash.cyber[itemIndex];
        var id = stashId(item); var m = MOD_BY[id]; if (!m) return;
        var q = QUALITY[m.quality] || QUALITY.gray;
        var on = stashSel.indexOf(itemIndex) >= 0;
        var chips = stashChips(item);
        html += '<button class="boon" data-stash="' + itemIndex + '" style="width:100%;margin-bottom:5px;border-color:' + (on ? q.color : 'rgba(120,140,160,.3)') + ';background:' + (on ? 'rgba(252,238,10,.07)' : 'transparent') + '"><b style="color:' + q.color + '">' + m.name + '</b><span class="tag">' + q.name + '</span>' + (chips.length ? '<span class="tag" style="color:#ffd166">芯片 ' + chips.length + '</span>' : '') + '<em style="display:block;font-style:normal;font-size:9px;color:#7fa">' + m.desc + '</em></button>';
      });
      html += '</div>';
      if (order.length > 8) html += '<button class="ghost" id="prepMore" style="margin-top:4px">' + (G._prepAll ? '收起' : '展开全部 ' + order.length + ' 件') + '</button>';
      if (META.stash.chips.length) html += '<div class="hint">仓库芯片 ' + META.stash.chips.length + ' 枚；未镶嵌的芯片留在仓库，已镶嵌的随义体一同带入</div>';
    }
    var pcap = 10 + Math.round(metaStatSum('adapt')) - ((typeof challengeMods === 'function' && challengeMods().adaptMinus) || 0), pload = 0;
    sel.forEach(function (id) { var m = MOD_BY[id]; if (m) pload += CYBER_COST[m.quality] || 1; });
    stashSel.forEach(function (ix) { var it = META.stash.cyber[ix], m = it && MOD_BY[stashId(it)]; if (!m) return; pload += (CYBER_COST[m.quality] || 1) + ((it.inst && (it.inst.plus || 0) + (it.inst.heavy || 0)) || 0); stashChips(it).forEach(function (c) { pload += c.heavy || 0; }); });
    html = html.replace('%%PGAUGE%%', prepGaugeHTML(pload, pcap));
    html += '<div class="dock"><button class="cta" id="prepGo">进入战斗' + (sel.length || stashSel.length ? ' · 带 ' + (sel.length + stashSel.length) + ' 件' : '') + '</button></div></div>';
    setOverlayHTML(html);
    overlay.classList.add('show');
    G.modal = 'prep'; G.paused = true; G.state = 'menu';
    $$('[data-pcyber]').forEach(function (b) {
      b.onclick = function () {
        var id = b.getAttribute('data-pcyber');
        if (stashSel.some(function (v) { return stashId(META.stash.cyber[v]) === id; })) { toast('仓库已选择同型号义体', 'warn'); return; }
        var i = sel.indexOf(id);
        if (i >= 0) sel.splice(i, 1);
        else if (sel.length < picks) sel.push(id);
        else { toast('最多选 ' + picks + ' 件', 'bad'); return; }
        render();
      };
    });
    $$('[data-pcons]').forEach(function (b) { b.onclick = function () { consSel = b.getAttribute('data-pcons'); render(); }; });
    $$('[data-stash]').forEach(function (b) { b.onclick = function () {
      var index = Number(b.getAttribute('data-stash')), id = stashId(META.stash.cyber[index]);
      var i = stashSel.indexOf(index);
      if (i >= 0) stashSel.splice(i, 1);
      else {
        if (stashSel.some(function (v) { return stashId(META.stash.cyber[v]) === id; })) { toast('同型号义体每局仅可带入一件', 'warn'); return; }
        stashSel.push(index); sel = sel.filter(function (v) { return v !== id; });
      }
      render();
    }; });
    if (rerolls > 0) {
      var rb = $('#prepReroll');
      if (rb) rb.onclick = function () { rerolls--; roll(); render(); };
    }
    var pm = $('#prepMore'); if (pm) pm.onclick = function () { G._prepAll = !G._prepAll; render(); };
    $('#prepGo').onclick = function () {
      if (META.pendingPrepTransfer && !reconcilePreparedTransfer()) { sfx.hurt(); return; }
      var selection = [], picked = { cybers: sel.slice(), cons: consSel, stash: [], stashItems: [], stashChips: [] };
      try {
        stashSel.forEach(function (index, ordinal) {
          var original = JSON.parse(JSON.stringify(META.stash.cyber[index]));
          var entry = typeof original === 'string' ? { id: original, chips: [] } : JSON.parse(JSON.stringify(original));
          entry._prepOrdinal = ordinal;
          selection.push({ ordinal: ordinal, originalIndex: index, entry: original });
          picked.stashItems.push(entry);
        });
      } catch (error) { console.error(error); sfx.hurt(); return; }
      if (selection.length) {
        var transfer = { id: Date.now().toString(36) + '-' + performance.now().toString(36), items: selection };
        var next = Object.assign({}, META, { stash: Object.assign({}, META.stash, {
          cyber: META.stash.cyber.filter(function (item, index) { return stashSel.indexOf(index) < 0; })
        }), pendingPrepTransfer: transfer });
        if (!saveJSON(META_KEY, next)) {
          var button = $('#prepGo'); if (button && button._label) button.innerHTML = button._label;
          sfx.hurt(); return;
        }
        META.stash = next.stash; META.pendingPrepTransfer = transfer;
        picked.transferId = transfer.id;
      }
      G.prepPick = picked; G._prepStarting = !!picked.transferId;
      try { startGame(); }
      catch (error) {
        G._prepStarting = false; reconcilePreparedTransfer(); sceneReset();
        G.state = 'menu'; G.paused = false; G.busy = false; G.prepPick = null; G.prepReceipt = null;
        console.error(error); sfx.hurt(); menuScreen();
      } finally { G._prepStarting = false; }
    };
    var pb = $('#prepBack'); if (pb) pb.onclick = function () { startFlow(2); };
    var pc = $('#prepChal'); if (pc) pc.onclick = function () { G._chalFromFlow = true; challengeScreen(); };
  }
  render();
}


