function openReloadPicker() {
  if (classDef().id !== 'assault' || G.state !== 'play' || G.paused || G.busy) return;
  if (G.ammo >= G.ammoMax) { msg('弹匣已满', 'dim'); return; }
  if (!G.inv.length) { msg('没有可用的消耗品，无法换弹', 'dim'); return; }
  if (G.inv.length === 1) { reloadWithItem(0); return; }
  showModal('reload');
  var html = '<div class="card"><div class="kicker">换弹 · 能量 ' + G.energy + '/' + G.energyMax + ' · 消耗 ' + gunReloadCost() + ' 能量</div>' +
    '<h1 class="title small">选择底材</h1><div class="sub">消耗品决定弹种</div><div class="cards">';
  G.inv.forEach(function (id, i) {
    var c = CONS[id];
    if (!c) return;
    var sp = id === 'mag_pack' ? null : specialFor(c);
    var flavor = sp ? SPECIALS[sp].name + ' · ' + SPECIALS[sp].desc : '普通弹';
    html += '<button class="boon" data-reload="' + i + '">' +
      '<b>' + c.name + '</b>' +
      '<span class="g">▲ ' + flavor + '</span>' +
      '<em style="display:block;font-style:normal;font-size:10px;color:#6f9bb0;margin-top:3px">消耗 1 件消耗品 + ' + gunReloadCost() + ' 能量，装满弹匣</em></button>';
  });
  html += '</div><button class="ghost" id="reloadClose">取消</button></div>';
  setOverlayHTML(html);
  $$('[data-reload]').forEach(function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.preventDefault();
      reloadWithItem(parseInt(btn.getAttribute('data-reload'), 10));
    });
  });
  $('#reloadClose').onclick = function () { hideOverlay(); };
}
function reloadWithItem(i) {
  if (classDef().id !== 'assault' || G.state !== 'play') return;
  var id = G.inv[i], c = CONS[id];
  if (!c) return;
  var ecost = gunReloadCost();
  if (G.energy < ecost) { toast('能量不足（需要 ' + ecost + '）', 'bad'); return; }
  if (G.ammo >= G.ammoMax) { msg('弹匣已满', 'dim'); return; }
  if (G.reload) { msg('正在换弹', 'dim'); return; }
  G.inv.splice(i, 1);
  G.energy -= ecost;
  G.ammo = 0;
  G.reload = { turns: reloadTurns(), max: reloadTurns(), special: (id === 'mag_pack') ? null : specialFor(c), name: c.name };
  hideOverlay();
  msg('换弹中 · ' + G.reload.turns + ' 回合' + (G.reload.special ? ' · 装填' + SPECIALS[G.reload.special].name : ''), 'warn');
  sfx.pick();
  updateHUD();
  endTurn();
}


