    if (rp && sit && sit.inst) rp.onclick = function () { if (!confirm2(rp)) return; var c = Math.round((8 + (sit.inst.maxDur - sit.inst.dur) * (4 + Q_ORDER.indexOf(smod.quality) * 1.5)) * (1 + (sit.inst.plus || 0) * .6)); if (META.cores < c) return; META.cores -= c; sit.inst.dur = sit.inst.maxDur; saveMeta(); sfx.level(); renderMarket(); };
