  $$('[data-mcat]').forEach(function (b) { b.onclick = function () { mk.cat = b.getAttribute('data-mcat'); renderMarket(); }; });
  $$('[data-mitem]').forEach(function (b) { b.onclick = function () { mk.item = b.getAttribute('data-mitem'); renderMarket(); }; });
