function startFloor() {
  stairPrompt = null; G.stairHold = null;
  G.hackedFields = []; G.hackedCorpses = [];
  if (G.corpOp && (G.corpOp.active || G.depth > G.corpOp.depth) && G.depth !== G.corpOp.depth) { G.corpOp = null; G.opWall = null; }
  if (G.trialKit && !G.corpOp) trialEnd(null);
  G.cams = []; G.cfence = []; G.cmines = []; G.corpStrikes = [];
  G.walls = []; G.stealth = 0; G.control = null; G.ghostRevealed = false; G.stance = null; G.hazards = []; G.mines = []; G.hazardTick = 0; G.melee = { charge: 0, combo: 0, step: 0 }; G.slash = null;
  var hadMerc = G.allies.some(function (a) { return a.kind === 'merc'; });
  var keepDrones = G.allies.filter(function (a) { return a.kind === 'drone'; });
  if (hadMerc) msg('雇来的人留在了上一层', 'dim');
  G.allies = keepDrones;
  genMap(G.depth);
  keepDrones.forEach(function (d) {
    var t = freeAdjacent(p.x, p.y);
    if (t) { d.x = t.x; d.y = t.y; }
  });
  computeFOV();
  G.log = [];
  G.floorDamage = 0;
  econFloorStart();
  if (G.prepReceipt) G.prepReceipt.ready = true;
  saveRun(true);
  if (isBossFloor(G.depth)) {
    msg('B' + G.depth + 'F · 守卫层', 'warn');
    if (G.bossIntro) msg('「' + G.bossIntro + '」', 'warn');
    msg('守卫：' + (G.bossName || '未知') + (G.depth === MAX_DEPTH ? ' · 击败它即可通关' : ' · 楼梯已上锁'), 'dim');
  } else {
    msg('B' + G.depth + 'F · 第' + stageOf(G.depth) + '区', 'sys');
    msg('检测到 ' + G.enemies.length + ' 个敌对信号' + ((G.sites || []).length ? ' · ' + G.sites.length + ' 处设施' : ''), 'dim');
    if (G.anomaly) msg('区域异常 · ' + ANOMALIES[G.anomaly].name + '：' + ANOMALIES[G.anomaly].desc, 'warn');
  }
  updateHUD();
}
function metaStatSum(key) {
  var v = 0;
  META_UP.forEach(function (u) { if (u.stat && u.stat[key]) v += u.stat[key] * Math.min(u.max || 99, metaLvl(u.id)); });
  return v;
}
