  if (mw) {
    var mprof = mw.melee;
    var stages = meleeStages(mprof);
    var stage = stages[(G.melee.seq || 0) % stages.length];
    var mst = (stage && stage.note) || (mprof.type === 'combo' ? '连击' : mprof.type === 'arc' ? '横扫' : mprof.type === 'alternate' ? '轮击' : '近战');
    var extra = (G.melee.charge > 0 ? ' · 蓄力' + G.melee.charge : '') + (G.melee.combo > 0 ? ' · 连击x' + G.melee.combo : '') + (stages.length > 1 ? ' · ' + ((G.melee.seq || 0) % stages.length + 1) + '/' + stages.length : '');
    html += '<span class="buff" style="color:' + (mprof.color || C.pink) + '">' + mw.name + ' · ' + mst + extra + '</span>';
  }
  if (classDef().id === 'ghost' && playerHidden()) html += '<span class="buff" style="color:' + C.green + '">隐身' + (Math.max(G.stealth, G.ghostStealth) > 0 ? ' ' + Math.max(G.stealth, G.ghostStealth) : '') + '</span>';
  else if (classDef().id === 'ghost' && G.ghostRevealed) html += '<span class="buff" style="color:' + C.red + '">显形</span>';
  // 临界由独立大条展示，不再重复小标签
  if (G.freeze > 0) html += '<span class="buff" style="color:' + C.cyan + '">时停 ' + G.freeze + '</span>';
  if (G.overheat > 0) html += '<span class="buff" style="color:' + '#ff7a45' + '">过热 ' + G.overheat + '</span>';
  if (G.overclock > 0) html += '<span class="buff" style="color:' + C.green + '">超频 ' + G.overclock + '</span>';
