    if (en.hp <= 0) return;
    var dmg = playerHit(en, effAtk() * 1.2, { source: 'mech-missile', origin: p }).damage;
    G.beams.push({ x0: p.x + 0.5, y0: p.y + 0.5, x1: en.x + 0.5, y1: en.y + 0.5, life: 260, max: 260, color: C.amber });
    burst(en.x, en.y, C.amber, 6);
    float(en.x, en.y, '-' + dmg, C.amber);
    if (en.hp <= 0) killEnemy(en);
