      gear: { eyeL: 'crit_chip', eyeR: 'target_analysis', handL: 'assault_hand_r', handR: 'smart_link', body: 'body_red', spine: 'assault_spine_r', legL: 'assault_leg_r', legR: 'legL_red' },
      chips: ['atk', 'crit', 'hp', 'def']
