  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x, y, bw, 16);
  ctx.fillStyle = b.color;
  ctx.fillRect(x + 1, y + 1, (bw - 2) * clamp(b.hp / b.maxHp, 0, 1), 14);
