    var pulse = attackAge >= 0 && attackAge < 220 ? Math.sin(attackAge / 220 * Math.PI) : 0;
    var facing = e.facing == null ? monArtFace(e) : e.facing;
    var offset = e.id === 'bl_lance' ? -tile * .18 * pulse : e.id === 'bl_hound' ? tile * .2 * pulse : 0;
