function econLive() { return !!(p && G.map && G.state === 'play' && G.mod); }
function econDepth() { return Math.max(1, G.depth || 1); }
function consPow(k, c) { return Math.max(1, Math.round(effAtk() * k + econDepth() * c)); }
function pctHp(f) { return Math.max(1, Math.round((p ? p.maxHp : 40) * f)); }
function econEsc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
function econVisible(e) { return e && e.hp > 0 && G.vis[e.y] && G.vis[e.y][e.x]; }
function econVisibleEnemies() { return G.enemies.filter(econVisible); }

/* ---------- 信用点 ---------- */
function gainCredits(n, x, y, quiet) {
  if (G.mode !== 'normal' || !p) return 0;
  n = Math.max(0, Math.round(n));
  if (!n) return 0;
  G.credits = (G.credits || 0) + n;
  if (!quiet) sfx.coin();
  G.creditPulse = Date.now();
  if (!quiet) float(x == null ? p.x : x, y == null ? p.y : y, '+¥' + n, '#ffd166');
  return n;
}
function killCredits(e) {
  if (G.loanFloors > 0 && !e.boss) return 0;
  var base = e.boss ? 30 + G.depth * 2 : e.bounty ? 24 : e.elite ? 5 : 2;
  base += Math.floor((G.depth - 1) / 5);
  var anom = ANOMALIES[G.anomaly];
  return Math.round(base * (anom && anom.credit ? anom.credit : 1));
}
function econPriceMul() { return (1 + (econDepth() - 1) * 0.07) * (1 - (G.shopDiscount || 0)) * ((G.chal && G.chal.priceMul) || 1); }
function econPrice(base) { return Math.max(1, Math.round(base * econPriceMul())); }
var CONS_PRICE = { common: 14, rare: 24, epic: 44 };
var RUN_CYBER_PRICE = { gray: 14, green: 22, blue: 34, purple: 52, orange: 80, red: 118 };
var CHIP_SELL = { gray: 3, green: 5, blue: 8, purple: 12, orange: 18, red: 26 };

/* ---------- 风险修正（委托条款 / 区域异常） ---------- */
function econDamageTakenMul() { var m = 1; if (contractHas('hunted')) m *= 1.25; if (G.anomaly === 'overdrive') m *= 1.25; return m; }
function econDamageDealtMul() { return G.anomaly === 'overdrive' ? 1.25 : 1; }
function econHealMul() { return contractHas('anemia') ? 0.5 : 1; }
function econHpMul() { return contractHas('glass') ? 0.8 : 1; }
function econEliteBonus() { return G.anomaly === 'lockdown' ? 0.2 : 0; }
function econVisionMod() { return G.anomaly === 'blackout' ? -2 : 0; }

