function shopOffer(kind) {
  var d = econDepth();
  if (kind === 'cons') { var c = pickConsumable(d + 1); return { kind: 'cons', id: c.id, price: econPrice(CONS_PRICE[c.tier || 'common']) }; }
  if (kind === 'cyber') { var m = lootCyber(d >= 8 ? 'blue' : 'green', []); if (!m) return shopOffer('chips'); return { kind: 'cyber', id: m.id, price: econPrice(RUN_CYBER_PRICE[m.quality] || 40) }; }
  if (kind === 'chips') {
    var chip = rollChipReward(lootChipQ('green'));
    return chip ? { kind: 'chip', chip: chip, price: econPrice(10 + Q_ORDER.indexOf(chip.quality) * 9) } : null;
  }
  if (kind === 'heal') return { kind: 'heal', price: econPrice(16) };
  if (kind === 'ammo') return { kind: 'ammo', price: econPrice(12) };
  return null;
}
function rollShopStock() {
  var list = [shopOffer('cons'), shopOffer('cons'), shopOffer('cyber'), shopOffer('chips'), shopOffer(classDef().id === 'assault' ? 'ammo' : 'heal')];
  return list.filter(Boolean);
}
function rollShop() { return rollShopStock(); }
