  $$('[data-enh]').forEach(function (b) { b.onclick = function () { var id = b.getAttribute('data-enh'), m = MOD_BY[id];
    enhanceScreen(id, instOf(id), { unit: '¥', cost: function (it) { return enhanceCost(it, m); }, can: function (it) { return (G.credits || 0) >= enhanceCost(it, m); }, pay: function (it) { G.credits -= enhanceCost(it, m); }, back: function () { openDoctor(s); } }); }; });
