  var terms = Object.keys(CONTRACT_TERMS).map(function (k) { var t = CONTRACT_TERMS[k]; return cxLine(t.name, '风险条款', [t.desc], '#ff9aa5'); }).join('');
  var tiers = Object.keys(CONTRACT_TIERS).map(function (k) { var t = CONTRACT_TIERS[k]; return cxLine(t.tag + ' · ' + t.name, '', [k === 'low' ? '本层内完成；报酬：信用点 + 消耗品；失败无惩罚' : k === 'high' ? '一条风险条款；报酬：信用点 + 加密数据箱 + 8 核心；失败没收 20% 信用点' : '押金 + 风险条款；报酬：信用点 + 押金双倍 + 黑墙保险箱 + 25 核心；失败永久违约'], t.color); }).join('');
