  if (pw === true) { toast('遗物 · ' + m.active.name, 'good'); msg('「' + m.name + '」' + RELIC_ONCE[once], 'warn'); G.cyberCd[id] = 0; computeFOV(); updateHUD(); endTurn(); return; }
