  if (m[0] === 'boss') return !!ST.bosses[m[1]];
  if (m[0] === 'win') return ST.wins >= 1;
  if (m[0] === 'win2') return ST.wins >= 2;
  if (m[0] === 'death3') return ST.deaths >= 3;
  if (m[0] === 'psycho') return ST.psycho >= 1;
