/* ---------- 雇佣兵 ---------- */
var MERC_SKILL_TEXT = { heal: '每 4 回合为你修复 12% 生命', shield: '每 4 回合为你提供护盾', strike: '每 4 回合对身边敌人重击', snipe: '每 4 回合狙击 6 格内敌人', emp: '每 5 回合让周围敌人宕机', bleed: '攻击附加流血' };
function mercAct(a) {
  var power = npcQualityPower(a.quality || corpZoneQ(G.depth));
  var ranged = a.fight === 'turret', e = nearestEnemyTo(a, ranged ? 6 : 8, true), atk = effAtk() * power;
  var distance = e ? cyberDistance(a, e) : Infinity;
  var skillInRange = e && los(a.x, a.y, e.x, e.y) && distance <= (a.skill === 'snipe' ? 6 : 1);
  a.cd = (a.cd || 0) - 1;
  if (a.cd <= 0) {
    a.cd = a.skill === 'emp' ? 5 : 4;
    if (a.skill === 'heal' && p.hp < p.maxHp) { healPlayer(pctHp(.12 * power)); G.beams.push({ x0: a.x + .5, y0: a.y + .5, x1: p.x + .5, y1: p.y + .5, life: 260, max: 260, color: C.green }); float(a.x, a.y, a.name, a.color); }
    else if (a.skill === 'shield') { addBuff('shield', 4, pctHp(.12 * power), a.name); float(a.x, a.y, a.name, a.color); }
    else if (a.skill === 'emp') { G.enemies.forEach(function (o) { if (!o.boss && Math.max(Math.abs(o.x - a.x), Math.abs(o.y - a.y)) <= Math.round(3 * power)) { o.stun = Math.max(o.stun || 0, Math.ceil(power)); o.intent = null; } }); nvSpawn(a.x, a.y, a.color, 20); }
    else if (skillInRange && (a.skill === 'snipe' || a.skill === 'strike')) { var h = playerHit(e, atk * (a.skill === 'snipe' ? 1.6 : 2), { source: 'merc', origin: a }); G.beams.push({ x0: a.x + .5, y0: a.y + .5, x1: e.x + .5, y1: e.y + .5, life: 260, max: 260, color: a.color }); float(e.x, e.y, '-' + h.damage, a.color, true); if (e.hp <= 0) killEnemy(e); return; }
    else a.cd = 1;
  }
  if (!e) { if (Math.max(Math.abs(a.x - p.x), Math.abs(a.y - p.y)) > 2) allyStep(a, p); return; }
  var d = Math.max(Math.abs(e.x - a.x), Math.abs(e.y - a.y));
  if (ranged ? d <= 6 && los(a.x, a.y, e.x, e.y) : d <= 1) {
    var hit = playerHit(e, atk * .6, { source: 'merc', origin: a });
    if (a.skill === 'bleed') e.bleedStacks = Math.min(6, (e.bleedStacks || 0) + 2);
    if (ranged) G.beams.push({ x0: a.x + .5, y0: a.y + .5, x1: e.x + .5, y1: e.y + .5, life: 180, max: 180, color: a.color });
    float(e.x, e.y, '-' + hit.damage, a.color); if (e.hp <= 0) killEnemy(e);
  } else if (!ranged || d > 6) allyStep(a, e);
}

