var DRINK_BUFF = { hp: '下次深潜：生命上限 +12', atk: '下次深潜：攻击 +2', credits: '下次深潜：开局 +¥40', adapt: '下次深潜：适应度 +4', item: '下次深潜：开局 2 件稀有消耗品', crit: '下次深潜：暴击 +6%', legend: '下次深潜：攻击 +1，生命上限 +8，适应度 +2' };
