  $$('[data-ldrink]').forEach(function (b) { b.onclick = function () { var L = ST.legends[+b.getAttribute('data-ldrink')]; if (META.cores < 40 || ST.pendingDrink) return; if (!confirm2(b)) return; META.cores -= 40; saveMeta(); ST.pendingDrink = { name: L.drink, buff: 'legend' }; ST.drinks++; storySave(); sfx.pick(); barScreen('drinks'); }; });
  $('#backMenu').onclick = menuBack;
