  dodge: ['轻灵', '滑步', '残影'], critMult: ['致命', '处刑', '断骨'], lifesteal: ['饥渴', '吸髓', '红线'], power: ['超频', '过压', '炽热'], compat: ['温顺', '亲和', '低噪']
