  reg('mon', MONSTERS); reg('boss', (window.NEON && window.NEON.bosses) || []); reg('lboss', BOSSES); reg('item', ITEMS); reg('cons', CONSUMABLES);
  reg('mod', MODS); reg('quest', QUESTS); reg('buff', BUFFS); reg('chal', CHALLENGES);
