    row('主动功率', pctS(cyberPower())) + row('发作率', pctS(cyberPsychosisChance()), '每次受击') + row('背包', bagItems().length) + '</div>' + Object.keys(CORPS).filter(function (k) { return corpCount(k) > 0; }).map(function (k) { var anyId = CORP_MODS.find(function (d) { return d.corp === k; }).id; return corpSetHTML(MOD_BY[anyId]); }).join('');
