  h += '<div class="loot-h">攻击与技能</div><div class="st-list">' + atk.map(function (a) { return '<div class="st-atk"><b>' + a[0] + '</b><span>' + a[1] + '</span><small>' + a[2] + '</small></div>'; }).join('') + '</div>';
