  (G.boons || []).forEach(function (id) { var b = BOONS.find(function (x) { return x.id === id; }); if (b && b.bad && Object.keys(b.bad).length) cur.push([b.name, Object.keys(b.bad).map(function (k) { return boonLine(k, b.bad[k]); }).join(' · ')]); });
