function showMarketChipConfirmation(source, chipId, quality) {
  if (!source || source.disabled || overlay.querySelector('.market-buy-dialog')) return;
  var price = chipPrice(quality), specimen = CHIPS.find(function (c) { return c.id === chipId; });
  if (!QUALITY[quality] || !specimen || META.cores < price) return;
  var dialog = document.createElement('div');
  dialog.className = 'market-buy-dialog';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  var panel = document.createElement('div');
  panel.className = 'market-buy-panel';
  var picture = document.createElement('div');
  picture.className = 'market-buy-chip';
  var icon = source.querySelector('.chipico');
  if (icon) {
    var clone = icon.cloneNode(true);
    clone.querySelectorAll('canvas').forEach(function (canvas) { delete canvas.dataset.hardwareDrawn; delete canvas.dataset.hardwareContextEvents; });
    picture.appendChild(clone);
  }
  var name = document.createElement('b');
  name.className = 'market-buy-name';
  name.textContent = QUALITY[quality].name + '·' + specimen.name;
  var actions = document.createElement('div');
  actions.className = 'market-buy-actions';
  var cancel = document.createElement('button');
  cancel.className = 'ghost'; cancel.type = 'button'; cancel.textContent = '返回';
  var buy = document.createElement('button');
  buy.className = 'cta'; buy.type = 'button'; buy.textContent = '确认购买 · ' + price + ' 核心';
  actions.append(cancel, buy); panel.append(picture, name, actions); dialog.appendChild(panel); overlay.appendChild(dialog);
  window.NeonPresentation.mount(overlay);
  interfaceFx.present(panel, true);
  var done = false;
  function close() {
    document.removeEventListener('keydown', keydown, true);
    dialog.remove();
    window.NeonPresentation.mount(overlay);
    if (source.isConnected) source.focus({ preventScroll: true });
  }
  function keydown(ev) {
    if (ev.key === 'Escape') { ev.preventDefault(); ev.stopImmediatePropagation(); close(); }
    else if (ev.key === 'Tab') { ev.preventDefault(); ev.stopImmediatePropagation(); (document.activeElement === cancel ? buy : cancel).focus(); }
    else if ((ev.key === 'Enter' || ev.key === ' ') && (document.activeElement === cancel || document.activeElement === buy)) {
      ev.preventDefault(); ev.stopImmediatePropagation(); document.activeElement.click();
    }
  }
  cancel.onclick = close;
  dialog.onclick = function (ev) { if (ev.target === dialog) close(); };
  buy.onclick = function () {
    if (done || META.cores < price) return;
    done = true; buy.disabled = true;
    META.cores -= price; META.stash.chips.push(makeChip(chipId, quality)); saveMeta(); sfx.pick(); close(); renderMarket();
  };
  document.addEventListener('keydown', keydown, true);
  cancel.focus({ preventScroll: true });
  sfx.step();
}
