    var boss = cv.getAttribute('data-boss') === '1', sil = cv.getAttribute('data-sil') === '1';
    var W = boss ? 112 : 72, H = W, dpr2 = Math.min(3, window.devicePixelRatio || 1);
    cv.width = W * dpr2; cv.height = H * dpr2; cv.style.width = W + 'px'; cv.style.height = H + 'px';
    var c2 = cv.getContext('2d'), savedCtx = ctx, savedP = p;
